ProjectRebirthBloodlineDesignData = {
{raceId=1,name="Human Bloodline",icon="Interface\\Icons\\Achievement_Character_Human_Male",designText="Supplied Bloodline design. Native Bloodline progress is not enabled.\n\nEnlightened Potential\nHuman Diplomacy: Additional +1% positive reputation per ten ranks, up to +10%. Add to native Diplomacy on the pre-aura processed base; do not compound; negative changes unchanged.\n\nEnlightened Resolve: A successful Every Man for Himself grants 7.5% haste for 40 seconds at rank 50, scaling linearly to 15% at rank 100.\n\nHow it grows: +0.1% per rank to Strength, Agility, Stamina, Intellect and Spirit.\n\nDesign milestones: 1, 25, 49, 50, 75, 100.",nativeEnabled=false},
{raceId=3,name="Dwarf Bloodline",icon="Interface\\Icons\\Achievement_Character_Dwarf_Male",designText="Supplied Bloodline design. Native Bloodline progress is not enabled.\n\nStoneborn Fortitude\nStoneblood: Reduce damage from Poison-, Disease-, or Bleed-classified effects by 0.1% per rank, reaching 10%. Apply once even when several classifications match.\n\nEarthen Bulwark: A successful Stoneform grants 7.5% reduced damage taken for 12 seconds at rank 50, scaling to 15% at rank 100.\n\nHow it grows: +0.1% per rank to Strength, Agility, Stamina, Intellect and Spirit.\n\nDesign milestones: 1, 25, 49, 50, 75, 100.",nativeEnabled=false},
{raceId=4,name="Night Elf Bloodline",icon="Interface\\Icons\\Achievement_Character_NightElf_Male",designText="Supplied Bloodline design. Native Bloodline progress is not enabled.\n\nMoonshadow Legacy\nLightfooted: Increase unmounted movement speed by 0.2% per rank, reaching 10% at rank 50 and 20% at rank 100. This replaces, rather than accompanies, the earlier fall-damage reduction.\n\nMoonlit Precision: At rank 50+, Shadowmeld allows movement during a short stealth window. Only after stealth ends, grant +3 to +6 percentage points of eligible melee/ranged/spell critical chance for 20 seconds and +10% to +20% additional unmounted movement speed for 6 seconds.\n\nHow it grows: +0.1% per rank to Strength, Agility, Stamina, Intellect and Spirit.\n\nDesign milestones: 1, 25, 49, 50, 75, 100.",nativeEnabled=false},
{raceId=7,name="Gnome Bloodline",icon="Interface\\Icons\\Achievement_Character_Gnome_Male",designText="Supplied Bloodline design. Native Bloodline progress is not enabled.\n\nIngenious Adaptation\nEfficient Mind: Reduce positive Mana, Energy, Rage and Runic Power costs by 0.05% per rank, reaching 5%. Do not change rune counts, combo points, health sacrifices or reagents.\n\nBrilliant Reversal: A successful Escape Artist grants +15% to +30% unmounted run speed for 6 seconds and a further 10% to 20% reduction of remaining eligible resource cost for 12 seconds.\n\nHow it grows: +0.1% per rank to Strength, Agility, Stamina, Intellect and Spirit.\n\nDesign milestones: 1, 25, 49, 50, 75, 100.",nativeEnabled=false},
{raceId=11,name="Draenei Bloodline",icon="Interface\\Icons\\Achievement_Character_Draenei_Male",designText="Supplied Bloodline design. Native Bloodline progress is not enabled.\n\nUnbroken Radiance\nUnbroken Spirit: Increase eligible healing received by 0.05% per rank, reaching 5%. Do not convert the modifier into a separate heal or absorb.\n\nNaaruâ€™s Aegis: A successful Gift of the Naaru grants its original valid recipient a 15-second absorb equal to 7.5% of the casterâ€™s maximum health at rank 50, scaling to 15% at rank 100.\n\nHow it grows: +0.1% per rank to Strength, Agility, Stamina, Intellect and Spirit.\n\nDesign milestones: 1, 25, 49, 50, 75, 100.",nativeEnabled=false},
{raceId=2,name="Orc Bloodline",icon="Interface\\Icons\\Achievement_Character_Orc_Male",designText="Supplied Bloodline design. Native Bloodline progress is not enabled.\n\nIndomitable Might\nIndomitable: Add 0.05 percentage points of stun-duration reduction per rank to the applicable native racial category, reaching +5 points at rank 100. This is not stun resistance chance or immunity.\n\nUnleashed Fury: Increase the actual native Blood Fury Attack Power and/or Spell Power bonus by 25% at rank 50 to 50% at rank 100, and extend that activation by 2 to 4 seconds.\n\nHow it grows: +0.1% per rank to Strength, Agility, Stamina, Intellect and Spirit.\n\nDesign milestones: 1, 25, 49, 50, 75, 100.",nativeEnabled=false},
{raceId=5,name="Forsaken Bloodline",icon="Interface\\Icons\\Achievement_Character_Undead_Male",designText="Supplied Bloodline design. Native Bloodline progress is not enabled.\n\nDeathless Will\nEfficient Cannibalization: Shorten Cannibalizeâ€™s channel by 0.25% per rank while preserving its total native healing, reaching a 25% shorter full channel at rank 100.\n\nUnshackled Hunger: After successful Will of the Forsaken, gain a 20-second window converting 5% to 10% of qualifying direct damage and effective healing into self-healing, capped at 0.5% to 1% of maximum health per second.\n\nHow it grows: +0.1% per rank to Strength, Agility, Stamina, Intellect and Spirit.\n\nDesign milestones: 1, 25, 49, 50, 75, 100.",nativeEnabled=false},
{raceId=6,name="Tauren Bloodline",icon="Interface\\Icons\\Achievement_Character_Tauren_Male",designText="Supplied Bloodline design. Native Bloodline progress is not enabled.\n\nEarthborn Endurance\nDeep Vitality: Increase maximum health by 0.1% per rank, reaching 5% at rank 50 and 10% at rank 100. This supersedes the previous 0.05% / 5% proposal.\n\nAncestral Shelter: A successful War Stomp grants a 15-second personal absorb equal to 7.5% of caster maximum health at rank 50, scaling to 15% at rank 100.\n\nHow it grows: +0.1% per rank to Strength, Agility, Stamina, Intellect and Spirit.\n\nDesign milestones: 1, 25, 49, 50, 75, 100.",nativeEnabled=false},
{raceId=8,name="Troll Bloodline",icon="Interface\\Icons\\Achievement_Character_Troll_Male",designText="Supplied Bloodline design. Native Bloodline progress is not enabled.\n\nPrimal Vitality\nLiving Regeneration: For each ten ranks, regenerate an additional 0.1% of maximum health every five seconds, including in combat: 0.5% at rank 50 and 1% at rank 100.\n\nBloodrush: Extend Berserking by 2.5 seconds at rank 50 to 5 seconds at rank 100 and restore a total 7.5% to 15% of maximum health evenly across that activation.\n\nHow it grows: +0.1% per rank to Strength, Agility, Stamina, Intellect and Spirit.\n\nDesign milestones: 1, 25, 49, 50, 75, 100.",nativeEnabled=false},
{raceId=10,name="Blood Elf Bloodline",icon="Interface\\Icons\\Achievement_Character_BloodElf_Male",designText="Supplied Bloodline design. Native Bloodline progress is not enabled.\n\nArcane Refinement\nArcane Resilience: Reduce incoming magical damage by 0.1% per rank, reaching 5% at rank 50 and 10% at rank 100. This supersedes the previous 0.05% / 5% proposal.\n\nArcane Imprint: A successful Arcane Torrent grants three charges lasting 20 seconds. Each improves the eligible direct damage, direct healing or absorb amount of the next qualifying player-activated ability by 10% at rank 50 to 20% at rank 100.\n\nHow it grows: +0.1% per rank to Strength, Agility, Stamina, Intellect and Spirit.\n\nDesign milestones: 1, 25, 49, 50, 75, 100.",nativeEnabled=false}
